/// </summary>
public class METCheckDigitLogicHelper
{
}

Method.Source:
    /// <summary>
    /// get the check digit for PE_CCD_1 
    /// </summary>
    /// <param name = "_numberSequence">numberSequence</param>
    /// <returns>check digit value</returns>
    public static int getCheckDigit_One(NumberSequenceCode _numberSequence)
    {
        int     numseq = str2Int(_numberSequence);
        int     i = 0;
        int     j = 0;

        while(numseq!=0)
        {
            j = (((numseq mod 10) *  (8 - i)) mod 10 ) + j;
            numseq = any2Int(numseq/10);
            j = j mod 10;
            i++;
        }
        if (j >= 10)
        {
            j  = j mod 10;
        }

        return j;
    }

    /// <summary>
    /// get the check digit for PE_CCD_2
    /// </summary>
    /// <param name = "_numberSequence">numberSequence</param>
    /// <returns>check digit value</returns>
    public static int getCheckDigit_Two(NumberSequenceCode _numberSequence)
    {
        int     numseq = str2Int(_numberSequence);
        int     v3 = 0;
        int     i, v4, v5, v7, v8, v9,v10;
        str     v2, v6;

        str abcde = subStr(_numberSequence, 3, 5);
        
        for (i = 1; i<= strLen(abcde); i++)
        {
            if ((i mod 2) != 0)
            {
                v2 = v2 + subStr(abcde, i,1);// odd position a,c,e
            }
            else
            {
                v3++;
                v6 = v6 + subStr(abcde, i,1);// even position b,d
            }
        }

        v4 = str2Int(v2) * 100;

        v5 = (v4*2);

        v7 = v5 + str2Int(v6);

        while(v7!=0)
        {
            v8 = (v7 mod 10) + v8;
            v7 = any2Int(v7/10);
        }
        if ((v8 mod 10) == 0)
        {
            v9 = v8;
        }
        v9 = any2Int(abs(v8 mod 10));
        if (v9!= 0)
        {
            v10 = 10-v9;
        }
        else
        {
            v10 = 0;
        }
        if (v10 >= 10)
        {
            v10  = v10 mod 10;
        }
        return v10;
    }

    /// <summary>
    /// get the check digit for PE_CCD_5
    /// </summary>
    /// <param name = "_numberSequence">numberSequence</param>
    /// <returns>check digit value</returns>
    public static int checkDigit_Five(NumberSequenceCode _numberSequence)
    {
        int i;
        int v2, v6, v7;

        for (i = 1; i<= strLen(_numberSequence); i++)
        {
            v2 = v2 + ((str2Int(subStr(_numberSequence, i,1))) * (7-i));
        }
        v6 = v2 mod 11;
        v7 = 11 - v6;
        if(v7 >= 10)
        {
            v7 = 0;
        }
        
        return v7;

    }

    /// <summary>
    /// get the check digit for HWE
    /// </summary>
    /// <param name = "_numberSequence">numberSequence</param>
    /// <returns>check digit value</returns>
    public static int checkDigit_HWE(NumberSequenceCode _numberSequence)
    {
        int     i, v2, total1, total2, total, result;

        for (i = 1; i<= strLen(_numberSequence); i++)
        {
            if ((i mod 2) != 0)
            {
                v2 = ((str2Int(subStr(_numberSequence, i,1))) * (2));
                if (v2>=10)
                {
                    v2 = (v2 mod 10) +1;
                }
                total1 += v2;
            }
            else
            {
                v2 = ((str2Int(subStr(_numberSequence, i,1))) * (1));
                if (v2>=10)
                {
                    v2 = (v2 mod 10) +1;
                }
                total2 += v2;
            }
        }
        total   = total1 + total2;
        result  = 10 - (total mod 10);
        if (result >= 10)
        {
            result  = result mod 10;
        }
        return result;
    }

    public static int getCheckDigitZZCD02(str _number) 
    {
        int len = strLen(_number);
        str selectedDigits = '';
        str skippedDigits = '';
        int i;
        int64 v2, v3, v4, v5, v6, v7;
        int digitSum =0;
        int checkDigit;
        str v7Str;

        //Step 2 take every 2nd digit from the right
        for(i = len; i >= 1; i--)
        {
            if(((len - i) mod 2 ) == 0)
            {
                selectedDigits = subStr(_number, i,1) + selectedDigits;
            }
            else
            {
                skippedDigits = skippedDigits + subStr(_number, i, 1);
            }
        }

        v2 = str2Int64(selectedDigits);

        // Step 3 collect all skipped digits

        v3 = strLen(skippedDigits);

        // step 4 Multiple V2 by 10 raised to the power of v3

        v4 = v2 * any2Int64(power(10, v3));

        // step 5 multiple v4 with 2

        v5 = v4 * 2;

        // step 6 Convert skipped digits to integer

        v6 = skippedDigits ? str2Int64(skippedDigits) : 0;

        // step 7 Add values from step 5 & 6

        v7 = v5 + v6;

        // Step 8 convert value from step 7 to string and add all digits

        v7Str = int642Str(v7);

        for(i=1; i <= strLen(v7str); i++)
        {
            digitSum += str2Int(subStr(v7Str, i,1));
        }

        //step 9 calculate check digit
        checkDigit = (10 - (digitSum mod 10)) mod 10;

        //step 10 return check digit
        return checkDigit;
    }
